// qaSerialMedia generates a tiny probeable mkv via ffmpeg's lavfi (the same
// generator the shipped integration fixtures use).
func qaSerialMedia(t *testing.T, path string) {
	t.Helper()
	mustMkdir(t, filepath.Dir(path))
	if err := exec.Command("ffmpeg",
		"-f", "lavfi",
		"-i", "testsrc=duration=0.3:size=16x16:rate=10",
		"-loglevel", "error",
		"-y",
		filepath.Clean(path),
	).Run(); err != nil {
		t.Fatalf("ffmpeg generate %s: %v", filepath.Base(path), err)
	}
}

// qaSerialCreateLibrary POSTs a SERIAL library and returns its id.
func qaSerialCreateLibrary(t *testing.T, c *http.Client, baseURL, token, root, name string) int64 {
	t.Helper()
	body := createLibraryRequest{ModuleID: "serial", RootPath: root, DisplayName: name}
	var resp libraryResponse
	if status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/libraries", token, body, &resp); status != http.StatusCreated {
		t.Fatalf("create serial library: HTTP %d, want 201", status)
	}
	return resp.ID
}

// qaSerialListSeries lists a library's series rows.
func qaSerialListSeries(t *testing.T, c *http.Client, baseURL, token string, libID int64) []qaSerialSeriesDTO {
	t.Helper()
	var resp qaSerialSeriesList
	url := baseURL + "/api/v1/series?library=" + strconv.FormatInt(libID, 10)
	if status := doRequest(t, c, http.MethodGet, url, token, nil, &resp); status != http.StatusOK {
		t.Fatalf("list series lib %d: HTTP %d, want 200", libID, status)
	}
	return resp.Items
}

// qaSerialGetSeries fetches one series by id, returning the series (zero on a
// non-200), the HTTP status, and the canonical error code (empty on 200).
func qaSerialGetSeries(t *testing.T, c *http.Client, baseURL, token, id string) (qaSerialSeriesDTO, int, string) {
	t.Helper()
	var resp qaSerialSeriesOrError
	status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/series/"+id, token, nil, &resp)
	return resp.Series, status, resp.Error.Code
}

// qaSerialSeriesDocument fetches one series' full document by id (fatals on a
// non-200).
func qaSerialSeriesDocument(t *testing.T, c *http.Client, baseURL, token, id string) json.RawMessage {
	t.Helper()
	sr, status, errCode := qaSerialGetSeries(t, c, baseURL, token, id)
	if status != http.StatusOK {
		t.Fatalf("GET /series/%s: HTTP %d (%s)", id, status, errCode)
	}
	return sr.Document
}

// qaSerialSeriesEpisodes lists a series' episode items in the item wire shape.
func qaSerialSeriesEpisodes(t *testing.T, c *http.Client, baseURL, token, seriesID string) []itemDTO {
	t.Helper()
	var resp itemsResponse
	if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/series/"+seriesID+"/episodes", token, nil, &resp); status != http.StatusOK {
		t.Fatalf("list episodes of %s: HTTP %d, want 200", seriesID, status)
	}
	return resp.Items
}

// qaSerialSeriesEpisodeRels maps a series' episode relative paths to their ids.
func qaSerialSeriesEpisodeRels(t *testing.T, c *http.Client, baseURL, token, seriesID string) map[string]string {
	t.Helper()
	out := map[string]string{}
	for _, it := range qaSerialSeriesEpisodes(t, c, baseURL, token, seriesID) {
		out[it.RelativePath] = it.ID
	}
	return out
}

// qaSerialItemByRel fetches the one item at rel (fatal when missing).
func qaSerialItemByRel(t *testing.T, c *http.Client, baseURL, token string, libID int64, rel string) itemDTO {
	t.Helper()
	for _, it := range listItems(t, c, baseURL, token, libID) {
		if it.RelativePath == rel {
			return it
		}
	}
	t.Fatalf("item %q not persisted in lib %d", rel, libID)
	return itemDTO{}
}

// qaSerialTryItem reports whether an item exists at rel (no fatal).
func qaSerialTryItem(t *testing.T, c *http.Client, baseURL, token string, libID int64, rel string) (itemDTO, bool) {
	t.Helper()
	for _, it := range listItems(t, c, baseURL, token, libID) {
		if it.RelativePath == rel {
			return it, true
		}
	}
	return itemDTO{}, false
}

// qaSerialWaitSettled polls both libraries until every series and episode row
// is ready (bounded — INV-poll-bounded), then returns.
func qaSerialWaitSettled(t *testing.T, c *http.Client, baseURL, token string, libIDs ...int64) {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		done := true
		for _, libID := range libIDs {
			for _, sr := range qaSerialListSeries(t, c, baseURL, token, libID) {
				if sr.Status != "ready" {
					done = false
				}
			}
			for _, it := range listItems(t, c, baseURL, token, libID) {
				if it.Status != "ready" {
					done = false
				}
			}
		}
		if done {
			return
		}
		time.Sleep(probeInterval)
	}
	for _, libID := range libIDs {
		for _, sr := range qaSerialListSeries(t, c, baseURL, token, libID) {
			if sr.Status != "ready" {
				t.Errorf("drain: series %q (lib %d) stuck at %q after %s", sr.RelativePath, libID, sr.Status, qaSerialDrainTimeout)
			}
		}
		for _, it := range listItems(t, c, baseURL, token, libID) {
			if it.Status != "ready" {
				t.Errorf("drain: item %q (lib %d) stuck at %q after %s", it.RelativePath, libID, it.Status, qaSerialDrainTimeout)
			}
		}
	}
}

// qaSerialAssertScanWarnings checks the per-serial deep-video warning surfaced
// through the scan result and that the junk produced NO warning.
func qaSerialAssertScanWarnings(t *testing.T, warnings []string) {
	t.Helper()
	found := false
	for _, w := range warnings {
		if strings.Contains(w, "smbdelete") {
			t.Errorf("scan warned about extensionless junk: %q (junk must be excluded silently)", w)
		}
		if strings.Contains(w, qaSerialDirS04) && strings.Contains(w, "Extras"+string(filepath.Separator)+"extra.mkv") {
			found = true
		}
	}
	if !found {
		t.Errorf("scan warnings %v lack the deep-video entry naming %q and Extras/extra.mkv", warnings, qaSerialDirS04)
	}
}

// qaSerialAssertSeriesSet asserts the series rows' relative paths and backing.
func qaSerialAssertSeriesSet(t *testing.T, series []qaSerialSeriesDTO, want map[string]string) {
	t.Helper()
	byRel := qaSerialSeriesByRel(series)
	for rel, backing := range want {
		sr, ok := byRel[rel]
		if !ok {
			t.Errorf("series row for %q missing (have %v)", rel, qaSerialRels(series))
			continue
		}
		doc := parseAsyncDoc(t, sr.Document)
		if doc.Parsed["serial_record"] != true {
			t.Errorf("series %q: parsed.serial_record = %v, want true", rel, doc.Parsed["serial_record"])
		}
		if got := asyncStr(doc.Parsed, "backing"); got != backing {
			t.Errorf("series %q: backing = %q, want %q", rel, got, backing)
		}
		if got := asyncStr(doc.Parsed, "series_relative_path"); got != rel {
			t.Errorf("series %q: series_relative_path = %q, want the identity path", rel, got)
		}
		if !strings.HasPrefix(sr.ID, "ser_") {
			t.Errorf("series %q: id %q lacks the ser_ prefix", rel, sr.ID)
		}
		if sr.Status != "pending" && sr.Status != "ready" {
			t.Errorf("series %q: status %q not in the scan-time lifecycle", rel, sr.Status)
		}
	}
}

// qaSerialSidecarWant is one expected sidecar fact.
type qaSerialSidecarWant struct {
	kind     string
	language string
	basis    string
}

// qaSerialAssertSidecars asserts an episode's sidecar facts as a set keyed by
// the sidecar relative path (order-independent).
func qaSerialAssertSidecars(t *testing.T, it itemDTO, want map[string]qaSerialSidecarWant) {
	t.Helper()
	got := qaSerialSidecarFacts(parseAsyncDoc(t, it.Document).Parsed, "sidecars")
	if len(got) != len(want) {
		t.Errorf("%q: sidecars = %v, want %d entries %v", it.RelativePath, got, len(want), want)
		return
	}
	byPath := map[string]map[string]any{}
	for _, sc := range got {
		byPath[qaSerialStr(sc, "relative_path")] = sc
	}
	for rel, w := range want {
		sc, ok := byPath[rel]
		if !ok {
			t.Errorf("%q: sidecar %q missing (have %v)", it.RelativePath, rel, qaSerialMapKeys(byPath))
			continue
		}
		if qaSerialStr(sc, "kind") != w.kind || qaSerialStr(sc, "language") != w.language || qaSerialStr(sc, "match_basis") != w.basis {
			t.Errorf("%q: sidecar %q = %v, want {kind=%s language=%q basis=%s}", it.RelativePath, rel, sc, w.kind, w.language, w.basis)
		}
	}
}

// qaSerialSidecarFacts reads a sidecar fact list out of a parsed map.
func qaSerialSidecarFacts(parsed map[string]any, key string) []map[string]any {
	raw, _ := parsed[key].([]any)
	out := make([]map[string]any, 0, len(raw))
	for _, e := range raw {
		if m, ok := e.(map[string]any); ok {
			out = append(out, m)
		}
	}
	return out
}

func qaSerialStr(m map[string]any, k string) string { s, _ := m[k].(string); return s }

// qaSerialSha16 is the first 16 lowercase hex chars of sha256 over the raw
// bytes — re-derived independently (matches the store's seriesID and the
// frame-grabber thumbPath scheme, design Interfaces §5/§7).
func qaSerialSha16(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])[:16]
}

// qaSerialSeriesID re-derives ser_<libraryID>_<sha16(relative_path)>.
func qaSerialSeriesID(libraryID int64, rel string) string {
	return "ser_" + strconv.FormatInt(libraryID, 10) + "_" + qaSerialSha16(rel)
}

func qaSerialSeriesByRel(series []qaSerialSeriesDTO) map[string]qaSerialSeriesDTO {
	out := make(map[string]qaSerialSeriesDTO, len(series))
	for _, sr := range series {
		out[sr.RelativePath] = sr
	}
	return out
}

func qaSerialRels(series []qaSerialSeriesDTO) []string {
	out := make([]string, 0, len(series))
	for _, sr := range series {
		out = append(out, sr.RelativePath)
	}
	return out
}

func qaSerialMapKeys[T any](m map[string]T) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}
